import { z } from "zod";

export const AddrSchema = z.object({
  city: z.string(),
  zip: z.string().optional(),
});
export type Addr = z.infer<typeof AddrSchema>;

export const ExtraItemSchema = z.object({
  deep: z.boolean(),
});
export type ExtraItem = z.infer<typeof ExtraItemSchema>;

export const RootItemSchema = z.object({
  id: z.number().int(),
  name: z.string().nullable(),
  tags: z.array(z.string()).optional(),
  addr: AddrSchema.optional(),
  active: z.boolean().optional(),
  extra: z.array(z.union([z.number().int(), ExtraItemSchema])).optional(),
});
export type RootItem = z.infer<typeof RootItemSchema>;

export const RootSchema = z.array(RootItemSchema);
export type Root = z.infer<typeof RootSchema>;

