convert.dart:
typedef Root = List<RootItem>;

class RootItem {
  final int id;
  final String? name;
  final List<String>? tags;
  final Addr? addr;
  final bool? active;
  final List<dynamic>? extra;

  const RootItem({
    required this.id,
    this.name,
    this.tags,
    this.addr,
    this.active,
    this.extra,
  });

  factory RootItem.fromJson(Map<String, dynamic> json) => RootItem(
    id: json['id'] as int,
    name: json['name'] as String?,
    tags: (json['tags'] as List<dynamic>?)?.map((e) => e as String).toList(),
    addr: json['addr'] == null ? null : Addr.fromJson(json['addr'] as Map<String, dynamic>),
    active: json['active'] as bool?,
    extra: json['extra'] as List<dynamic>?,
  );

  Map<String, dynamic> toJson() => {
    'id': id,
    'name': name,
    if (tags != null) 'tags': tags,
    if (addr != null) 'addr': addr?.toJson(),
    if (active != null) 'active': active,
    if (extra != null) 'extra': extra,
  };
}

class Addr {
  final String city;
  final String? zip;

  const Addr({
    required this.city,
    this.zip,
  });

  factory Addr.fromJson(Map<String, dynamic> json) => Addr(
    city: json['city'] as String,
    zip: json['zip'] as String?,
  );

  Map<String, dynamic> toJson() => {
    'city': city,
    if (zip != null) 'zip': zip,
  };
}

